SELECT COUNT(subq_1.Accepted_tickets_measure) AS Accepted_tickets, subq_1.day AS day, dim_agent.agent_team AS agent_team FROM (SELECT CASE WHEN fact_ticket_event_log.event_type = 'accept' THEN fact_ticket_event_log.ticket_id END AS Accepted_tickets_measure, dateTrunc('day', event_timestamp) AS day, ticket_id AS ticket FROM fact_ticket_event_log WHERE 1 = 1) AS subq_1 JOIN fact_ticket_journey AS fact_ticket_journey ON subq_1.ticket = fact_ticket_journey.ticket_id JOIN dim_agent AS dim_agent ON fact_ticket_journey.final_agent_id = dim_agent.agent_id GROUP BY day, agent_team